// This file demonstrates how to run the compiled binary in a test environment.\n// It is not required for the core functionality but serves as an example.\n\n#[cfg(test)]\nmod integration {\n    use std::process::Command;\n\n    #[test]\n    fn cli_with_seed() {\n        // Mock rationale: ensure the CLI prints the deterministic quest when --seed is supplied.\n        let output = Command::cargo_bin("nightly-epic-quest-generator")\n            .expect("binary exists")\n            .args(["--seed", "42"])\n            .output()\n            .expect("failed to execute process");\n        let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();\n        assert_eq!(\n            stdout,\n            "Quest: Retrieve the Whispering Amulet from the Sunken Library guarded by the Crimson Dragon."\n        );\n    }\n}\n
